<?php
namespace App\Http\Controllers;use App\Models\AiPrompt;use App\Models\User;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
class AiPromptController extends Controller{public function index(Request $r):JsonResponse{$u=$this->user($r);$q=$r->validate(['search'=>['nullable','string','max:200']])['search']??'';$items=AiPrompt::query()->where('account_id',$u->id)->when($q,fn($x)=>$x->where(fn($y)=>$y->where('title','like',"%{$q}%")->orWhere('category','like',"%{$q}%")->orWhere('description','like',"%{$q}%")))->latest()->get();return response()->json(['data'=>['prompts'=>$items]]);}public function store(Request $r):JsonResponse{$u=$this->user($r);$d=$this->data($r);return response()->json(['data'=>['prompt'=>AiPrompt::query()->create([...$d,'account_id'=>$u->id])]],201);}public function update(Request $r,AIPrompt $prompt):JsonResponse{$u=$this->user($r);abort_unless($prompt->account_id===$u->id,404);$prompt->update($this->data($r));return response()->json(['data'=>['prompt'=>$prompt->fresh()]]);}public function destroy(Request $r,AIPrompt $prompt):JsonResponse{$u=$this->user($r);abort_unless($prompt->account_id===$u->id,404);$prompt->delete();return response()->json([],204);}private function data(Request $r):array{return $r->validate(['title'=>['required','string','max:160'],'category'=>['required','string','max:80'],'description'=>['nullable','string','max:1000'],'prompt'=>['required','string','max:20000']]);}private function user(Request $r):User{$u=$r->user();abort_unless($u,401);return $u;}}
